int main(){g_world.build();auto& K=g_career;int pro=club("FRA",0),ama=club("FRA",8);check(pro>=0&&ama>=0,"fixtures");SportingProfile P;P.nation=g_world.nationIndex("FRA");P.start=1;P.reputation=55;P.experience=15;K.sportingStart(pro,2026,P);auto& S=K.sporting;check(K.sportingMode()&&S.employed&&K.season.controlled==std::vector<int>{pro},"distinct human sporting mode");check(!K.life.isPlayer&&!K.mgr.fullManager,"human not a player or field manager");check(S.coaches.size()==1&&S.agents.size()==24&&!S.network.empty(),"coach and commercial network initialized");for(auto skill:S.profile.skills)check(skill>=10&&skill<=99,"15 bounded skills");check(std::string(K.director.profile.name)=="Jean Martin","human profile used by transfer workflows");check(K.managerName==S.coaches[0].name,"coach recorded separately");auto rng=g_rng.s;K.sportingPrepare(pro);check(g_rng.s==rng,"coach profile selection leaves match RNG unchanged");auto& T=g_world.teams[pro];T.formation=(S.coaches[0].formation+1)%NUM_FORMATIONS;T.xi.clear();K.sportingPrepare(pro);check(T.formation==S.coaches[0].formation&&T.xi.size()==11,"AI restores its tactics and lineup");int before=S.profile.skills[SD_VISION];K.sportingLearn(SD_VISION,200);check(S.profile.skills[SD_VISION]==before+2,"skills evolve with experience");std::string msg;generous();S.power=0;check(!K.sportingSpend(77,200000,100,msg),"major fee needs chairman approval");check(K.sportingBoard(77,200000,100,msg),"chairman board decision");bool approved=K.sportingSpend(77,200000,100,msg);if(!approved)printf("REASON %s payroll %lld staffcap %lld\n",msg.c_str(),(long long)K.wageBill(pro),(long long)K.director.limits.wageCap);check(approved,"chairman approves exact proposal");check(!K.sportingSpend(78,200000,100,msg)&&!K.sportingSpend(77,200001,100,msg),"approval cannot authorize another player or increased amount");int fa=freeAgentsTeam();g_world.ensureSquad(fa);int target=g_world.teams[fa].squad.back().id;int64_t cash=K.mgr.budget;check(K.signPlayer(target,200000,100,3,msg)==-2&&K.mgr.budget==cash&&g_world.findPlayer(target)==fa,"real signature cannot bypass chairman or spend funds");K.mgr.budget=-1;check(!K.sportingBoard(77,1,0,msg)&&!K.sportingSpend(77,0,0,msg),"negative cash restricts spending");generous();K.mgr.dncg=1;check(!K.sportingBoard(77,1,0,msg),"French DNCG cannot be overridden");K.mgr.dncg=0;S.power=0;auto c=sportingCoachCandidate(pro,1,123);S.staffBudget=100000;check(!K.sportingHireCoach(c,true,msg),"limited power cannot dismiss coach alone");S.approvedCoach=1;check(K.sportingHireCoach(c,true,msg),"approved coach change charges indemnity");int ci=-1,mi=-1;for(int i=0;i<(int)K.season.comps.size()&&ci<0;i++)for(int j=0;j<(int)K.season.comps[i].matches.size();j++){auto& m=K.season.comps[i].matches[j];if(m.home==pro||m.away==pro){ci=i;mi=j;break;}}check(ci>=0,"own match exists");K.season.comps[ci].matches[mi].hg=1;K.season.comps[ci].matches[mi].ag=0;K.sportingMatch(ci,mi);int trust=S.trust;K.sportingMatch(ci,mi);check(S.trust==trust&&S.matchKeys.size()==1,"match report is idempotent");S.plan[0]=0;S.plan[2]=2;check(K.sportingProject(msg),"project accepted");trust=S.trust;K.sportingProject(msg);check(S.trust==trust,"resubmitting project cannot farm confidence");S.trust=80;S.profile.skills[SD_DIPLOMACY]=80;check(K.sportingMeeting(0,msg)&&!K.sportingMeeting(1,msg),"one decision meeting per month");check(K.save("build/test-build8.sav")&&K.load("build/test-build8.sav"),"save31 roundtrip");check(S.active&&S.employed&&S.agents.size()==24&&S.matchKeys.size()==1&&S.planApproved,"all sidecar state persists");K.sportingLeave(0,"Test departure");check(!S.employed&&!K.directorEnabled()&&K.season.controlled.empty()&&!S.jobs.empty(),"unemployed state has no club mandate");check(!K.sportingSpend(1,0,0,msg),"former club spending forbidden");int job=S.jobs[0].club;check(K.sportingApply(job,false,msg)&&S.employed&&K.userTeam==job&&S.history.size()==2,"club switch preserves human career history");P.start=0;P.reputation=15;K.sportingStart(pro,2026,P);check(!S.employed,"beginner cannot start with a professional club");K.sportingStart(ama,2026,P);check(S.employed&&S.power<=1&&S.wage==0,"amateur director volunteers under limited powers");
 // Ten complete annual transitions; only the selected championship is simulated in this bounded regression fixture.
 for(int n=0;n<10;n++){int p,q,g;check(K.tierOfTeam(K.userTeam,&p,&q,&g)>=0,"club enrolled each season");int selected=K.pyramids[p].pools[q].comps[g];for(int i=0;i<(int)K.season.comps.size();i++)if(i!=selected){auto& C=K.season.comps[i];C.done=true;for(auto& st:C.stages)st.finished=true;}K.season.advance(true);check(K.season.finished,"selected championship completes");S.trust=90;S.coachTrust=80;if(S.contractYears<=1)check(K.sportingRenew(msg),"human mandate renewed in final contract season");S.objective=4;K.mgr.budget=100000;K.mgr.noSack=true;int yr=K.year;K.endSeason();check(K.year==yr+1&&S.profile.age==P.age+n+1,"year and human age advance once");check(S.active&&S.employed&&S.history.back().seasons==n+1,"ten-season mandate and statistics");check(K.season.controlled==std::vector<int>{K.userTeam},"next-season championship control maintained");check(S.transferBudget>=0&&S.matchKeys.empty(),"annual budget and match ledger reset");}
 check(K.save("build/test-build8-ten-seasons.sav")&&K.load("build/test-build8-ten-seasons.sav"),"ten-season career reload");if(FILE* f=fopen("build/test-legacy-v30.sav","rb")){fclose(f);check(K.load("build/test-legacy-v30.sav")&&!K.sportingMode(),"true build7 save remains compatible");}
 FILE* f=tmpfile();K.sporting=SportingCareer();K.sporting.power=99;Writer w{f};sportingSave(w,K);rewind(f);Reader r{f};sportingLoad(r,K);check(!r.ok,"invalid sporting state rejected");fclose(f);printf("PASS build8 sporting: %d checks; ten annual championship transitions\n",checks);}
